-- Report ID : RPT_062
-- Report    : Pack Discontinued 7 Days
-- Module    : Replenishment
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     TRUNC(SYSDATE)                                        AS report_date,     TRUNC(SYSDATE) - TRUNC(pil.STATUS_UPDATE_DATE)       AS days_since_discontinued,      cim.DEPT                                              AS dept_no,     d.DEPT_NAME                                           AS dept_name,     cim.CLASS                                             AS class_no,     c.CLASS_NAME                                          AS class_name,     cim.SUBCLASS                                          AS subclass_no,     sc.SUB_NAME                                           AS subclass_name,      pi.ITEM                                               AS consumer_item_id,     cim.ITEM_DESC                                         AS consumer_item_desc,     cim.STANDARD_UOM                                      AS consumer_uom,     cim.STATUS                                            AS consumer_item_status,      pim.ITEM                                              AS pack_item_id,     pim.ITEM_DESC                                         AS pack_item_desc,     pim.PACK_IND                                          AS pack_ind,     pi.PACK_QTY                                           AS component_qty_in_pack,      pil.STATUS                                            AS pack_loc_status,     'Discontinued'                                        AS pack_loc_status_desc,     pil.STATUS_UPDATE_DATE                                AS pack_disc_date,      pil.LOC                                               AS location_id,     pil.LOC_TYPE                                          AS loc_type,     CASE pil.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                   AS loc_type_desc,     CASE pil.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS location_name,      cil.STATUS                                            AS consumer_loc_status,     CASE cil.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                   AS consumer_loc_status_desc,      ril.REPL_METHOD                                       AS repl_method,     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'DI' THEN 'Dynamic - Issues'         WHEN 'S'  THEN 'Dynamic - Seasonal'         WHEN 'TI' THEN 'Time Supply - Issues'         WHEN 'E'  THEN 'Time Supply - Seasonal'         ELSE ril.REPL_METHOD     END                                                   AS repl_method_desc,     ril.STOCK_CAT                                         AS stock_category,     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'         ELSE ril.STOCK_CAT     END                                                   AS stock_category_desc,     ril.REPL_ORDER_CTRL                                   AS order_control,     ril.MIN_STOCK                                         AS min_stock,     ril.MAX_STOCK                                         AS max_stock,      ril.PRIMARY_PACK_NO                                   AS current_primary_repl_pack,     CASE         WHEN ril.PRIMARY_PACK_NO IS NULL         THEN 'NO PACK CONFIGURED - ORDERING AT UNIT LEVEL'         WHEN ril.PRIMARY_PACK_NO = pim.ITEM         THEN 'CONFIGURED TO DISC PACK - UPDATE REQUIRED'         ELSE 'CONFIGURED TO DIFFERENT PACK - VERIFY'     END                                                   AS pack_setup_status,      ril.PRIMARY_REPL_SUPPLIER                             AS repl_supplier_id,     sp.SUP_NAME                                           AS supplier_name,      cils.STOCK_ON_HAND                                    AS consumer_current_soh,     cils.AV_COST                                          AS consumer_wac,     cil.SELLING_UNIT_RETAIL                               AS consumer_unit_retail,     ROUND(cils.STOCK_ON_HAND * cils.AV_COST, 2)          AS consumer_soh_value,      pils.STOCK_ON_HAND                                    AS pack_current_soh,      CASE         WHEN ril.PRIMARY_PACK_NO IS NULL              AND ril.REPL_METHOD IS NOT NULL         THEN 'HIGH - Consumer replenishing at unit level, pack just discontinued'         WHEN ril.PRIMARY_PACK_NO = pim.ITEM         THEN 'CRITICAL - Primary repl pack is the discontinued pack'         ELSE 'MEDIUM - Review pack configuration'     END                                                   AS risk_level,      CASE         WHEN ril.PRIMARY_PACK_NO IS NULL         THEN 'Assign alternative simple pack as Primary Pack on REPL_ITEM_LOC'         WHEN ril.PRIMARY_PACK_NO = pim.ITEM         THEN 'Remove discontinued pack from PRIMARY_PACK_NO and assign active replacement'         ELSE 'Verify current PRIMARY_PACK_NO is active and valid for this supplier'     END                                                   AS recommended_action  FROM     MFCS_RDS.RDS_WV_ITEM_MASTER             pim      JOIN  MFCS_RDS.RDS_WV_PACKITEM          pi    ON  pim.ITEM        = pi.PACK_NO      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER       cim   ON  pi.ITEM         = cim.ITEM      JOIN  MFCS_RDS.RDS_WV_DEPS              d     ON  cim.DEPT        = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS             c     ON  cim.DEPT        = c.DEPT                                                   AND  cim.CLASS       = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS          sc    ON  cim.DEPT        = sc.DEPT                                                   AND  cim.CLASS       = sc.CLASS                                                   AND  cim.SUBCLASS    = sc.SUBCLASS      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC          pil   ON  pim.ITEM        = pil.ITEM                                                   AND  pil.STATUS      = 'C'                                                   AND  TRUNC(pil.STATUS_UPDATE_DATE)                                                        >= TRUNC(SYSDATE) - 7      JOIN  MFCS_RDS.RDS_WV_REPL_ITEM_LOC    ril   ON  pi.ITEM          = ril.ITEM                                                   AND  pil.LOC          = ril.LOCATION                                                   AND  ril.REPL_METHOD IS NOT NULL                                                   AND  (                                                        ril.PRIMARY_PACK_NO IS NULL                                                        OR ril.PRIMARY_PACK_NO != pim.ITEM                                                   )      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC      cil   ON  pi.ITEM         = cil.ITEM                                                   AND  pil.LOC         = cil.LOC                                                   AND  pil.LOC_TYPE    = cil.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  cils  ON  pi.ITEM         = cils.ITEM                                                   AND  pil.LOC         = cils.LOC                                                   AND  pil.LOC_TYPE    = cils.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  pils  ON  pim.ITEM        = pils.ITEM                                                   AND  pil.LOC         = pils.LOC                                                   AND  pil.LOC_TYPE    = pils.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_STORE          st   ON  pil.LOC         = st.STORE                                                   AND  pil.LOC_TYPE    = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH             wh   ON  pil.LOC         = wh.WH                                                   AND  pil.LOC_TYPE    = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_SUPS           sp   ON  ril.PRIMARY_REPL_SUPPLIER = sp.SUPPLIER  WHERE     pim.PACK_IND = 'Y'  ORDER BY     CASE         WHEN ril.PRIMARY_PACK_NO IS NULL AND ril.REPL_METHOD IS NOT NULL         THEN 'HIGH - Consumer replenishing at unit level, pack just discontinued'         WHEN ril.PRIMARY_PACK_NO = pim.ITEM         THEN 'CRITICAL - Primary repl pack is the discontinued pack'         ELSE 'MEDIUM - Review pack configuration'     END,     TRUNC(SYSDATE) - TRUNC(pil.STATUS_UPDATE_DATE),     d.DEPT_NAME,     cim.ITEM_DESC,     CASE pil.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END